// Filtre générique : une option n'apparaît que si le poste 'requiresPost' a une
// vraie valeur ≠ 'requiresOptionNot' actuellement sélectionnée. Généré depuis
// requires_post / requires_option_not (onglet 4) — remplace l'ancienne règle codée
// en dur spécifique au cintre/potence kit cadre, désormais générique à tout poste.
function passesRequiresGate(opt, selOpts) {
  if (!opt.requiresPost) return true;
  const current = selOpts[opt.requiresPost];
  return !!current && current !== opt.requiresOptionNot;
}